package com.primehr.rewardsrecognition;
import com.primehr.rewardsrecognition.domain.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import static org.assertj.core.api.Assertions.*;
class RrEvaluationDomainTest{@Test void eligibilityQuorumDecisionAndReconsiderationPreserveLifecycle(){var c=new RrEvaluationCase("A","N","C","CAT","CH",1,"fp");c.decideEligibility(RrEvaluationCase.Status.ELIGIBLE,"All requirements verified","EMP-1",Instant.now());c.beginEvaluation();c.beginDeliberation(new BigDecimal("91.2500"));assertThatThrownBy(()->c.recommend(true,3,1,false)).hasMessageContaining("quorum");c.recommend(true,3,2,true);c.finalDecision(true);c.requestReconsideration();c.resolveReconsideration(false);assertThat(c.getStatus()).isEqualTo(RrEvaluationCase.Status.FINAL_DISAPPROVED);}@Test void weightedScoreIsServerDerivedAndBounded(){var criterion=new RrAwardCriterion("A","CAT","IMPACT","Impact",null,new BigDecimal("40"),new BigDecimal("10"),"Evidence",1);var rating=new RrCriterionRating("A","ASG",criterion,new BigDecimal("8"),"Verified evidence");assertThat(rating.getWeightedScore()).isEqualByComparingTo("32.0000");assertThatThrownBy(()->new RrCriterionRating("A","ASG",criterion,new BigDecimal("11"),"x")).isInstanceOf(IllegalArgumentException.class);}}
